DO $$\nDECLARE\n  user1_id UUID;\n  user2_id UUID;\n  conv_id UUID;\nBEGIN\n  -- 1. Get User IDs from usernames\n  SELECT id INTO user1_id FROM public.profiles WHERE username = 'tester1';\n  SELECT id INTO user2_id FROM public.profiles WHERE username = 'drian';\n\n  -- Check if users were found\n  IF user1_id IS NULL OR user2_id IS NULL THEN\n    RAISE EXCEPTION 'Could not find one or both users: @tester1, @drian';\n  END IF;\n\n  -- 2. Find the conversation ID they share\n  SELECT conversation_id INTO conv_id\n  FROM public.conversation_participants\n  WHERE user_id IN (user1_id, user2_id)\n  GROUP BY conversation_id\n  HAVING COUNT(DISTINCT user_id) = 2\n  LIMIT 1;\n\n  -- Check if a conversation was found\n  IF conv_id IS NOT NULL THEN\n    -- 3. Delete the messages from that conversation\n    DELETE FROM public.messages\n    WHERE conversation_id = conv_id;\n    RAISE NOTICE 'SUCCESS: The chat history between @tester1 and @drian has been deleted.';\n  ELSE\n    RAISE NOTICE 'INFO: No conversation was found between @tester1 and @drian.';\n  END IF;\nEND $$;